-- TEST DATA ONLY. Generated by supabase/demo/gen_demo_sites.mjs; do not edit by hand.
-- Re-seeds the demo sites (ramesh-kumar-pune, priya-sharma-jaipur) with the website-v2 starter content and links
-- their agents to the demo company 'demo-life' (approved). Run as postgres in the SQL Editor AFTER
-- every migration (20261022090000_multi_company.sql included) and supabase/demo/demo_offers.sql.
-- Idempotent. Keeps each site's contact section, hero photo and designation (they never leave the database).
begin;

-- Company links: a pending request, then approved (the memberships guard only allows that path). Each link needs
-- at least one insurance type (DECISIONS #89); the demo company is a life insurer.
insert into public.company_memberships (agent_id, company_id, insurance_types)
select s.agent_id, c.id, array['life']
  from public.sites s
  join public.companies c on c.slug = 'demo-life'
 where s.slug in ('ramesh-kumar-pune', 'priya-sharma-jaipur') and s.deleted_at is null
   and not exists (select 1 from public.company_memberships m
                    where m.agent_id = s.agent_id and m.company_id = c.id and m.status in ('pending', 'approved'));
update public.company_memberships m
   set status = 'approved'
  from public.sites s, public.companies c
 where s.slug in ('ramesh-kumar-pune', 'priya-sharma-jaipur') and s.deleted_at is null
   and c.slug = 'demo-life' and m.agent_id = s.agent_id and m.company_id = c.id and m.status = 'pending';

-- ramesh-kumar-pune: classic (personal), en
update public.sites s
   set template_key = 'classic',
       accent = 'indigo',
       locale = 'en',
       draft_content = v.content,
       published_content = v.content,
       published_at = now()
  from (select s2.id,
               '{"hero":{"headline":"Hello, I''m Ramesh Kumar","subheadline":"Life cover, savings, your children''s future and retirement: honest advice for you and your family in Pune, at every step."},"about":{"bio":"Hello, I''m Ramesh Kumar, and my work is helping families feel secure about tomorrow. Whether you''re buying your first policy, planning your child''s education or thinking about retirement, I''ll explain your choices clearly and help you decide with confidence. No jargon, no pressure, just honest guidance.","languagesSpoken":["english"]},"services":{"offered":["term","endowment","child","pension","health"],"items":[{"interest":"term","description":"High cover at a low premium, so your family stays financially secure if something happens to you."},{"interest":"endowment","description":"Protection and regular saving in one plan, with a benefit at maturity as per the policy terms."},{"interest":"child","description":"Plan ahead for your child''s education and milestones, with cover that keeps the plan going even if you''re not there."},{"interest":"pension","description":"Build a regular income for retirement, so you stay independent and comfortable in your later years."},{"interest":"health","description":"Cover for hospital bills and medical emergencies for you and your family, so your savings stay safe."}]},"highlights":{"items":[{"icon":"support_agent","title":"Personal guidance","text":"One person to call for every question, from our first meeting onwards."},{"icon":"schedule","title":"Timely reminders","text":"No missed premiums: you''ll hear from me well before each due date."},{"icon":"handshake","title":"Honest advice","text":"No pressure and no jargon, just clear answers you can trust."},{"icon":"verified_user","title":"Help with claims","text":"If you ever need to claim, I''ll guide your family through every step."}]},"faq":{"items":[{"question":"How much life cover do I need?","answer":"There''s no single number. I look at what your family would need to keep going, such as daily expenses, loans and children''s studies, and at what you already have. Then we choose cover that fits your budget."},{"question":"What is the difference between term insurance and a savings plan?","answer":"Term plans focus on protecting your family at a low cost. Savings plans help you build money for goals like a child''s education, along with some cover, as per the plan''s terms. The right mix depends on your needs, and I''ll walk you through it."},{"question":"Which documents do I need to buy a policy?","answer":"The basics are simple: identity proof, address proof, a photo and bank details. Depending on the plan and the cover amount, income proof or a health check-up may also be asked for. I''ll tell you exactly what''s needed before we start."},{"question":"How can I pay my premium?","answer":"You can choose a payment mode that suits your cash flow: yearly, half-yearly, quarterly or monthly. Paying online or by auto-debit is the easiest way, and I''ll send you a reminder before each due date. Tax benefits may apply as per prevailing tax laws."},{"question":"Will you help with claims?","answer":"Of course. A claim is when you need support the most. I''ll explain what''s needed, help you fill in the forms, gather the documents with you and follow up until you have an answer."}]},"sectionOrder":["hero","about","services","offers","highlights","achievements","testimonials","faq","contact"],"hidden":["achievements","testimonials","offers"]}'::jsonb
               || jsonb_build_object('contact', coalesce(s2.published_content -> 'contact', s2.draft_content -> 'contact', '{}'::jsonb))
               || jsonb_build_object('hero', ('{"headline":"Hello, I''m Ramesh Kumar","subheadline":"Life cover, savings, your children''s future and retirement: honest advice for you and your family in Pune, at every step."}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('photo', s2.published_content #> '{hero,photo}')))
               || jsonb_build_object('about', ('{"bio":"Hello, I''m Ramesh Kumar, and my work is helping families feel secure about tomorrow. Whether you''re buying your first policy, planning your child''s education or thinking about retirement, I''ll explain your choices clearly and help you decide with confidence. No jargon, no pressure, just honest guidance.","languagesSpoken":["english"]}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('designation', s2.published_content #> '{about,designation}')))
               as content
          from public.sites s2
         where s2.slug = 'ramesh-kumar-pune' and s2.deleted_at is null) v
 where s.id = v.id;

-- priya-sharma-jaipur: spotlight (offers), en
update public.sites s
   set template_key = 'spotlight',
       accent = 'maroon',
       locale = 'en',
       draft_content = v.content,
       published_content = v.content,
       published_at = now()
  from (select s2.id,
               '{"hero":{"headline":"Hello, I''m Priya Sharma","subheadline":"I help families in Jaipur choose the right life and health cover, explained simply and with no pressure."},"about":{"bio":"I''m Priya Sharma, an insurance advisor. I help families protect what matters most: their income, their children''s future and their retirement. I take the time to understand your needs, explain every option in plain words and suggest only what fits your budget. And I stay with you after the policy is issued, from premium reminders to claims. Call or WhatsApp me any time.","languagesSpoken":["english"]},"services":{"offered":["term","endowment","child","pension","health"],"items":[{"interest":"term","description":"High cover at a low premium, so your family stays financially secure if something happens to you."},{"interest":"endowment","description":"Protection and regular saving in one plan, with a benefit at maturity as per the policy terms."},{"interest":"child","description":"Plan ahead for your child''s education and milestones, with cover that keeps the plan going even if you''re not there."},{"interest":"pension","description":"Build a regular income for retirement, so you stay independent and comfortable in your later years."},{"interest":"health","description":"Cover for hospital bills and medical emergencies for you and your family, so your savings stay safe."}]},"highlights":{"items":[{"icon":"support_agent","title":"Personal guidance","text":"One person to call for every question, from our first meeting onwards."},{"icon":"schedule","title":"Timely reminders","text":"Renewals and due dates tracked for you, so nothing slips through."},{"icon":"handshake","title":"Honest advice","text":"I suggest only what you need and explain the costs up front."},{"icon":"verified_user","title":"Help with claims","text":"Support when it matters most, with the paperwork done together."}]},"faq":{"items":[{"question":"How much life cover do I need?","answer":"A common starting point is about 10 to 15 times your yearly income, plus any loans you have. The right amount depends on your family, your goals and your budget, so let''s work it out together in a short chat."},{"question":"What is the difference between term insurance and a savings plan?","answer":"Think of term insurance as pure protection: the highest cover for the lowest premium, with no payout if you outlive the term. Savings plans add a maturity benefit, which means a higher premium. Many families combine the two. Let''s see what suits you."},{"question":"Which documents do I need to buy a policy?","answer":"For most plans you need KYC documents (identity and address proof, such as Aadhaar and PAN), a photograph and bank details. For larger cover, income proof and a medical test may be needed. Don''t worry, I''ll help you get everything ready."},{"question":"How can I pay my premium?","answer":"Yearly, half-yearly, quarterly or monthly: pick what fits your budget. You can pay online, set up auto-debit or pay at a branch. I keep track of your due dates and remind you in time. Any tax benefit applies as per prevailing tax laws."},{"question":"Will you help with claims?","answer":"Yes. If you or your family ever need to make a claim, I''ll guide you through the forms and documents and stay in touch with the insurer at every step."}]},"sectionOrder":["hero","offers","services","highlights","about","testimonials","achievements","faq","contact"],"hidden":["achievements","testimonials"]}'::jsonb
               || jsonb_build_object('contact', coalesce(s2.published_content -> 'contact', s2.draft_content -> 'contact', '{}'::jsonb))
               || jsonb_build_object('hero', ('{"headline":"Hello, I''m Priya Sharma","subheadline":"I help families in Jaipur choose the right life and health cover, explained simply and with no pressure."}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('photo', s2.published_content #> '{hero,photo}')))
               || jsonb_build_object('about', ('{"bio":"I''m Priya Sharma, an insurance advisor. I help families protect what matters most: their income, their children''s future and their retirement. I take the time to understand your needs, explain every option in plain words and suggest only what fits your budget. And I stay with you after the policy is issued, from premium reminders to claims. Call or WhatsApp me any time.","languagesSpoken":["english"]}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('designation', s2.published_content #> '{about,designation}')))
               as content
          from public.sites s2
         where s2.slug = 'priya-sharma-jaipur' and s2.deleted_at is null) v
 where s.id = v.id;

commit;

-- Check (public data only): both sites render with offers and no company name.
select s.slug, s.template_key,
       jsonb_array_length(coalesce(public.get_public_site(s.slug) #> '{offers,items}', '[]'::jsonb)) as offers,
       public.get_public_site(s.slug) -> 'company' as company
  from public.sites s where s.slug in ('ramesh-kumar-pune', 'priya-sharma-jaipur');
